        responses: {
            /** @description Arming accepted. The zone may now be counting down an exit delay (state `arming`) or already armed (`exit_delay_s: 0`). */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["AlarmArmAccepted"];
                };
            };
            400: components["responses"]["BadRequest"];
            /** @description The zone's code policy requires an arm code and the supplied `code` is missing or wrong. The detail stays opaque (`invalid_code`) so a prober learns nothing about which codes exist. */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            404: components["responses"]["NotFound"];
            /** @description Arming refused — readiness blockers are present for the requested mode. The problem detail's `errors` array carries the blocker list (mirrors AlarmModeReadiness.blockers). */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
        };
